components.css:
.ds-button {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 50px;
  padding: 8px 16px;
  background: var(--white,#fff);
  color: var(--blue,#2544bd);
  font-size: 15px;
  font-weight: 800;
  text-decoration: none;
}
.ds-button:hover { background: var(--blue-light,#e8edfb); }
.ds-button svg { flex: 0 0 20px; width: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

.ds-signal-board {
  list-style: none;
  margin: 0;
  padding: 0;
  background: var(--paper,#f8f9f6);
  color: var(--ink,#1c2829);
  border: 1px solid var(--paper,#f8f9f6);
}
.ds-signal-board li {
  display: grid;
  grid-template-columns: clamp(74px, 10vw, 130px) minmax(0, 1fr);
  align-items: stretch;
  min-height: clamp(82px, 11vw, 130px);
}
.ds-signal-board li + li { border-top: 1px solid var(--rule,#b5bdb8); }
.ds-signal-board strong {
  align-content: center;
  padding: 12px clamp(13px, 2vw, 25px);
  font: 800 clamp(24px, 3.1vw, 43px)/.97 var(--display,"Barlow Condensed", sans-serif);
  text-wrap: balance;
}
.ds-signal-board li:last-child { background: var(--blue-light,#e8edfb); color: var(--blue,#2544bd); }
.ds-signal-icon {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  color: var(--blue,#2544bd);
  border-right: 1px solid var(--rule,#b5bdb8);
}
.ds-signal-icon i { display: block; }
.ds-signal-people i {
  width: clamp(10px, 1.55vw, 20px);
  height: clamp(10px, 1.55vw, 20px);
  border: 2px solid currentColor;
  border-radius: 50%;
}
.ds-signal-people i:nth-child(2) { background: currentColor; translate: 0 -7px; }
.ds-signal-shows i { width: clamp(9px, 1.35vw, 17px); height: clamp(22px, 3.3vw, 42px); border: 2px solid currentColor; }
.ds-signal-shows i:nth-child(2) { background: currentColor; }
.ds-signal-shows i:nth-child(3) { transform: rotate(-12deg); }
.ds-signal-episodes i { width: 3px; height: 19px; background: currentColor; }
.ds-signal-episodes i:nth-child(3) { height: 45px; }
